package com.nori.tc.db.jpa.common.entity.outbox;

import java.time.OffsetDateTime;

import com.nori.tc.db.domain.common.outbox.MsgSendResult;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.PrePersist;
import jakarta.persistence.Table;

/**
 * tc_msg_send_log 테이블 매핑 엔티티.
 *
 * [DB 스키마]
 * - send_log_key    : bigint generated by default as identity (PK)
 * - msg_key         : bigint NOT NULL (FK -> tc_msg_send_queue.msg_key, ON DELETE CASCADE)
 * - attempt_no      : int NOT NULL (>= 1)
 * - result          : varchar(16) NOT NULL (SUCCESS/FAIL)
 * - kafka_partition : int NULL
 * - kafka_offset    : bigint NULL
 * - error_code      : varchar(64) NULL
 * - error_message   : text NULL
 * - sent_at         : timestamptz NOT NULL default CURRENT_TIMESTAMP
 *
 * [설계 포인트]
 * 1. MapStruct 호환성:
 * - public 생성자를 제공하여 Mapper가 객체를 생성할 수 있게 합니다.
 *
 * 2. 기본값 방어:
 * - sentAt이 null이면 현재 시각으로 보정합니다.
 */
@Entity
@Table(name = "tc_msg_send_log")
public class TcMsgSendLogEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "send_log_key", nullable = false)
    private Long sendLogKey;

    @Column(name = "msg_key", nullable = false)
    private Long msgKey;

    @Column(name = "attempt_no", nullable = false)
    private Integer attemptNo;

    @Enumerated(EnumType.STRING)
    @Column(name = "result", length = 16, nullable = false)
    private MsgSendResult result;

    @Column(name = "kafka_partition")
    private Integer kafkaPartition;

    @Column(name = "kafka_offset")
    private Long kafkaOffset;

    @Column(name = "error_code", length = 64)
    private String errorCode;

    @Column(name = "error_message", columnDefinition = "text")
    private String errorMessage;

    @Column(name = "sent_at", nullable = false)
    private OffsetDateTime sentAt;

    // =========================================================================
    // Constructors (MapStruct & JPA)
    // =========================================================================

    /**
     * 기본 생성자 (필수)
     */
    public TcMsgSendLogEntity() {
    }

    /**
     * 전체 인자 생성자
     */
    public TcMsgSendLogEntity(
            Long sendLogKey,
            Long msgKey,
            Integer attemptNo,
            MsgSendResult result,
            Integer kafkaPartition,
            Long kafkaOffset,
            String errorCode,
            String errorMessage,
            OffsetDateTime sentAt
    ) {
        this.sendLogKey = sendLogKey;
        this.msgKey = msgKey;
        this.attemptNo = attemptNo;
        this.result = result;
        this.kafkaPartition = kafkaPartition;
        this.kafkaOffset = kafkaOffset;
        this.errorCode = errorCode;
        this.errorMessage = errorMessage;
        this.sentAt = sentAt;
    }

    // =========================================================================
    // Static Factory
    // =========================================================================

    public static TcMsgSendLogEntity newEntity(long msgKey, int attemptNo) {
        if (msgKey <= 0) {
            throw new IllegalArgumentException("msgKey must be positive");
        }
        if (attemptNo < 1) {
            throw new IllegalArgumentException("attemptNo must be >= 1");
        }
        TcMsgSendLogEntity e = new TcMsgSendLogEntity();
        e.setMsgKey(msgKey);
        e.setAttemptNo(attemptNo);
        return e;
    }

    // =========================================================================
    // Lifecycle
    // =========================================================================

    /**
     * DB Insert 전 기본값 방어
     * - sentAt이 null이면 현재 시각으로 보정합니다.
     */
    @PrePersist
    private void applyDefaults() {
        if (this.sentAt == null) {
            this.sentAt = OffsetDateTime.now();
        }
    }

    // =========================================================================
    // Getters & Setters
    // =========================================================================

    public Long getSendLogKey() {
        return sendLogKey;
    }

    public void setSendLogKey(Long sendLogKey) {
        this.sendLogKey = sendLogKey;
    }

    public Long getMsgKey() {
        return msgKey;
    }

    public void setMsgKey(Long msgKey) {
        this.msgKey = msgKey;
    }

    public Integer getAttemptNo() {
        return attemptNo;
    }

    public void setAttemptNo(Integer attemptNo) {
        this.attemptNo = attemptNo;
    }

    public MsgSendResult getResult() {
        return result;
    }

    public void setResult(MsgSendResult result) {
        this.result = result;
    }

    public Integer getKafkaPartition() {
        return kafkaPartition;
    }

    public void setKafkaPartition(Integer kafkaPartition) {
        this.kafkaPartition = kafkaPartition;
    }

    public Long getKafkaOffset() {
        return kafkaOffset;
    }

    public void setKafkaOffset(Long kafkaOffset) {
        this.kafkaOffset = kafkaOffset;
    }

    public String getErrorCode() {
        return errorCode;
    }

    public void setErrorCode(String errorCode) {
        this.errorCode = errorCode;
    }

    public String getErrorMessage() {
        return errorMessage;
    }

    public void setErrorMessage(String errorMessage) {
        this.errorMessage = errorMessage;
    }

    public OffsetDateTime getSentAt() {
        return sentAt;
    }

    public void setSentAt(OffsetDateTime sentAt) {
        this.sentAt = sentAt;
    }
}
